public class Main {
    public static void main(String[] args) {
        System.out.println("3x3 Multiplication Table Grid:");

        for (int row = 1; row <= 3; row++) {
            for (int col = 1; col <= 3; col++) {
                int product = row * col;
                System.out.print(product + "	");
            }
            System.out.println(); // Newline after each row
        }
    }
}

