public class Main {
    public static void main(String[] args) {
        for (int row = 1; row <= 3; row++) {
            for (int col = 1; col <= row; col++) {
                if (col == row) {
                    System.out.print(col);
                } else {
                    System.out.print(col + " ");
                }
            }
            System.out.println();
        }
    }
}

public class Main {
    public static void main(String[] args) {
        for (int x = 0; x <= 1; x++) {
            for (int y = 0; y <= 2; y++) {
                if (y == 2) {
                    System.out.print("(" + x + ", " + y + ")");
                } else {
                    System.out.print("(" + x + ", " + y + ") ");
                }
            }
            System.out.println();
        }
    }
}

public class Main {
    public static void main(String[] args) {
        for (int r = 3; r >= 1; r--) {
            for (int c = 1; c <= r; c++) {
                if (c == r && r == 1) {
                    System.out.print("*");
                } else if (c == r) {
                    System.out.print("*");
                } else {
                    System.out.print("* ");
                }
            }
            System.out.println();
        }
    }
}

public class Main {
    public static void main(String[] args) {
        for (int r = 1; r <= 3; r++) {
            for (int c = 1; c <= 3; c++) {
                if (c == 3) System.out.print(r);
                else System.out.print(r + " ");
            }
            System.out.println();
        }
    }
}

public class Main {
    public static void main(String[] args) {
        int total = 0;
        for (int i = 1; i <= 2; i++) {
            for (int j = 1; j <= 3; j++) {
                total += i * j;
            }
        }
        System.out.println("Total Product Sum: " + total);
    }
}

public class Main {
    public static void main(String[] args) {
        outer: for (int i = 1; i <= 5; i++) {
            for (int j = 1; j <= 5; j++) {
                if (i * j == 6) {
                    System.out.println("Target found: " + i + " * " + j + " = 6");
                    break outer;
                }
            }
        }
    }
